#[inline] pub fn find_sys_asset(id: &[u8]) -> Option<&'static VectorAsset> {
    for a in SYS_ASSETS { if a.id == id { return Some(a); } } None
}
#[inline] pub fn sys_shapes(asset: &VectorAsset) -> &'static [VectorShape] {
    let (s, e) = (asset.start as usize, asset.start as usize + asset.len as usize);
    SYS_SHAPES.get(s..e).unwrap_or(&[])
}
